const TaxCode*
lookup (Class cls, const char* entity, const char* code)
{
    if (entity == nullptr || code == nullptr)
        return nullptr;
    struct Table { Class cls; const char* entity; const TaxCode* codes;
                   size_t count; };
    static const Table tables[] = {
        {Class::Asset, "F1040", asset_f1040, 6},
        {Class::Asset, "F1065", asset_f1065, 17},
        {Class::Asset, "F1120", asset_f1120, 18},
        {Class::Asset, "F1120S", asset_f1120s, 18},
        {Class::Asset, "Other", asset_other, 1},
        {Class::Expense, "F1040", expense_f1040, 269},
        {Class::Expense, "F1065", expense_f1065, 127},
        {Class::Expense, "F1120", expense_f1120, 40},
        {Class::Expense, "F1120S", expense_f1120s, 98},
        {Class::Expense, "Other", expense_other, 1},
        {Class::Income, "F1040", income_f1040, 200},
        {Class::Income, "F1065", income_f1065, 53},
        {Class::Income, "F1120", income_f1120, 31},
        {Class::Income, "F1120S", income_f1120s, 40},
        {Class::Income, "Other", income_other, 1},
        {Class::LiabEq, "F1040", liabeq_f1040, 1},
        {Class::LiabEq, "F1065", liabeq_f1065, 7},
        {Class::LiabEq, "F1120", liabeq_f1120, 11},
        {Class::LiabEq, "F1120S", liabeq_f1120s, 10},
        {Class::LiabEq, "Other", liabeq_other, 1},
    };
    for (const Table& table : tables)
    {
        if (table.cls != cls || g_strcmp0 (table.entity, entity) != 0)
            continue;
        for (size_t index = 0; index < table.count; ++index)
        {
            if (g_strcmp0 (table.codes[index].code, code) == 0)
                return &table.codes[index];
        }
    }
    return nullptr;
}

